package net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TargetVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property target of observed alert rule ")
  void test_target_v_o_builder() {
    Assertions.assertFalse(TargetVO.nullValue().getTarget().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(TargetVO.tryFrom(null).getTarget().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", TargetVO.from("one").getTarget().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TargetVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TargetVO.from("one").toString());
  }
}
